  str_homeland_secret_msg_10209 = "Sariel comprou algumas centenas de pares das mesmas meias para que ela possa substituí-las a tempo quando elas rasgarem.",
  str_homeland_secret_msg_10210 = "Eu vi Sariel cozinhando comida com água preta no outro dia...",
  str_homeland_secret_msg_10211 = "SarielOs pais de 's costumavam ser nobres de Lumopolis!",
  str_homeland_secret_msg_10212 = "Desde então Eicy mudou-se para o dormitório, gritos estranhos podem ser ouvidos à noite...",
  str_homeland_secret_msg_10213 = "Eicy parece ser Victoriafilha de. É por isso que ela ouve Victoria.",
  str_homeland_secret_msg_10214 = "Eicy poderia fazer todos seguirem seu comando se ela tirasse o tapa-olho.",
  str_homeland_secret_msg_10215 = "A palavra lá fora é que Eicy sempre visita o Navigator tarde da noite...",
  str_homeland_secret_msg_10216 = "Há poucos meses atrás, Migard saiu do seu caminho para ficar com o Navigator por um tempo. É por isso que ela sabe tanto sobre os celestitas.",
  str_homeland_secret_msg_10217 = "Você ouviu aquele som estranho de farfalhar? Parece vir de Migardanimal de estimação.",
  str_homeland_secret_msg_10218 = "Migard uma vez quis rebocar o Soroz para a Illumina e desmontá-lo.",
  str_homeland_secret_msg_10219 = "Migard parece querer transformar os aposentos em um laboratório... Puxa...",
  str_homeland_secret_msg_10220 = "Corax lavou as mãos por uma noite inteira alguns dias atrás. O que está acontecendo...?",
  str_homeland_secret_msg_10221 = "Corax é realmente um reparador. Foi ele quem remendou o Colosso pela última vez.",
  str_homeland_secret_msg_10222 = "CoraxAs mãos de estão geladas... ao contrário de uma pessoa viva.",
  str_homeland_secret_msg_10223 = "Benny é muito melhor que Curo em uma luta!",
  str_homeland_secret_msg_10224 = "A pontuação de tiro de Curo é muito maior que a de Benny.",
  str_homeland_secret_msg_10225 = "Tanto Benny quanto Curo pediram casamento ao Navigator há alguns dias. Disseram que o Navigator é o \"alvo\" deles...",
  str_homeland_secret_msg_10226 = "Cuscuta não gosta de dormir na cama, então ela sempre dorme na natureza.",
  str_homeland_secret_msg_10227 = "Quão estranho é que um grande jardineiro como Cuscuta só cultiva rosas negras...",
  str_homeland_secret_msg_10228 = "Cuscuta parece ter sentimentos especiais pelo Navigator...",
  str_homeland_secret_msg_10229 = "Retire os espinhos Areiacorpo de, e ela cairia.",
  str_homeland_secret_msg_10230 = "AreiaA espada mágica de fala. Diz que cresceu com Areia.",
  str_homeland_secret_msg_10231 = "Eu vi o Navegador chorando Areia apenas alguns dias atrás...",
  str_homeland_secret_msg_10232 = "SikareA pequena caixa de sua família contém pistas sobre o tesouro escondido de sua família...",
  str_homeland_secret_msg_10233 = "eu ouvi isso Sikare é casado! Isso é verdade!?",
  str_homeland_secret_msg_10234 = "\"Bola de neve\" parece ser o nome do cachorro que Sikare costumava guardar.",
  str_homeland_secret_msg_10235 = "Eu vi Beverly e Charon juntos discutindo algum drama!",
  str_homeland_secret_msg_10236 = "Há alguns dias, vi o Navegador voando por aí, montado na lança relâmpago que Beverly conjurou!",
  str_homeland_secret_msg_10237 = "CarleenA lança de parece ser feita por Beverly.",
  str_homeland_secret_msg_10238 = "Constantine parece ter estado na Terra do Norte. Ele até serviu a rainha Bethlehem como seu guarda-costas.",
  str_homeland_secret_msg_10239 = "Constantine realmente não sabe usar uma arma. Ele geralmente apenas atinge os inimigos com a coronha da arma.",
  str_homeland_secret_msg_10240 = "Lester esteve em muitos lugares, até mesmo no Extremo Oriente!",
  str_homeland_secret_msg_10241 = "Lester refere-se a todos como \"senhor\", independentemente de seu sexo ou idade...",
  str_homeland_secret_msg_10242 = "eu ouvi isso Lester planeja se aposentar de seu emprego atual e trabalhar como gerente no dormitório.",
  str_homeland_secret_msg_10243 = "SylvaA mão de 's poderia se transformar em uma espada longa!",
  str_homeland_secret_msg_10244 = "Sylva pode transformar madeira em ferro.",
  str_homeland_secret_msg_10245 = "Ansia fala bem baixinho. É por isso que ela usa um alto-falante.",
  str_homeland_secret_msg_10246 = "Ansia provavelmente queria se juntar ao Rediesel Wrench, apenas pela música deles ou algo assim.",
  str_homeland_secret_msg_10247 = "Na realidade, Ansia tem ótima visão. Ela pode até ver a cor do olho de um pássaro de longe.",
  str_homeland_secret_msg_10248 = "Tessa é ótimo no boxe. Ela foi a campeã o ano todo em Umbraton!",
  str_homeland_secret_msg_10249 = "Tudo de Tessaos dentes de são falsos. É por isso que ela não precisa fugir dos doces!",
  str_homeland_secret_msg_10250 = "Eu vi Tessa e Smokey compras na rua de Umbraton. Eles até tomaram uma bebida... Hmmm...",
  str_homeland_secret_msg_10251 = "Eu ouvi isso enquanto Leah está por perto, não haveria falta de água fresca no dormitório.",
  str_homeland_secret_msg_10252 = "Há alguns dias, vi o Navigator flutuar até o topo de uma colina próxima em Leaha bolha!",
  str_homeland_secret_msg_10253 = "Qualquer flor Leah toques floresceriam instantaneamente!",
  str_homeland_secret_msg_10254 = "Última vez, Novio pensamento Alice era uma coelhinha e a levou para o Palácio de Inverno.",
  str_homeland_secret_msg_10255 = "AliceDiz-se que as duas bonecas de 's foram apanhadas na natureza quando ela estava sonâmbula uma vez.",
  str_homeland_secret_msg_10256 = "Alice adora comida picante. Ela pode até cuspir fogo depois!",
  str_homeland_secret_msg_10257 = "A garrafa de água em SinsaO cinto de 's contém água fria e quente para Eve.",
  str_homeland_secret_msg_10258 = "Sinsa faz um shish kabob matador. Da última vez ele até disse que preferia ser um vendedor de shish kabob do que um líder.",
  str_homeland_secret_msg_10259 = "Eu vi Sinsa prendendo o Navegador pela última vez, murmurando algo como \"Você não pode fazer isso\".",
  str_homeland_secret_msg_10260 = "ouvi Eve uma vez vestiu algo especial apenas para o Navigator!",
  str_homeland_secret_msg_10261 = "Eve faz visitas a Seleucid muitas vezes ultimamente, quase tratando-o como um grande gato.",
  str_homeland_secret_msg_10262 = "Eve parece ser capaz de levantar o Soroz apenas com uma mão.",
  str_homeland_secret_msg_10263 = "Da última vez, eu vi Eve, Sinsa, e o Navegador fazendo um piquenique juntos. Eve até disse que eles são uma \"família\" ou algo assim...",
  str_homeland_secret_msg_10264 = "Eu vi Dawn dando Eve flores no outro dia. Eles devem ser...",
  str_homeland_secret_msg_10265 = "A Garganta do Olho Vermelho pertence a Dawn, mas foi dado ao Navegador, ouvi dizer.",
  str_homeland_secret_msg_10266 = "Dawn usado para levantar Eclipses!",
  str_homeland_secret_msg_10267 = "Tudo Taki poderia tomar é um copo de vinho.",
  str_homeland_secret_msg_10268 = "Taki só veio para Umbraton porque perdeu tudo o que possuía jogando no Extremo Oriente.",
  str_homeland_secret_msg_10269 = "Taki's Odd Jobs não teve nenhum emprego ultimamente. Vai sair do mercado em breve!",
  str_homeland_secret_msg_10270 = "Há muito mais cristais vermelhos ultimamente no dormitório. Alguém ganhou na loteria e começou a deixar pedras preciosas por aí?",
  str_homeland_secret_msg_10271 = "Beryl fui ver Faust alguns dias atrás. Ruídos estranhos foram ouvidos vindos de Faustquarto de...",
  str_homeland_secret_msg_10272 = "Há rumores de que Beryl costumava ser um nobre de Lumopolis. Ela fugiu quando sua família entrou em algum tipo de problema.",
  str_homeland_secret_msg_10273 = "BerylAs lágrimas de se transformam em rubis!",
  str_homeland_secret_msg_10274 = "Smokey parece ter derrotado uma manticora no passado! Essa era uma criatura lendária!",
  str_homeland_secret_msg_10275 = "Smokey parece não sentir nenhuma dor.",
  str_homeland_secret_msg_10276 = "Quando Smokey chegou em Umbraton, ela queimou uma rua inteira...",
  str_homeland_secret_msg_10277 = "Smokey possui centenas de pares de óculos de sol e usa um par diferente todos os dias.",
  str_homeland_secret_msg_10278 = "Você sabe sobre aquele lagarto gigante em Rediesel Wrench? Fleur criou!",
  str_homeland_secret_msg_10279 = "Fleur parece ter sido sequestrado por uma mulher com um revólver e entregue a Rediesel Wrench.",
  str_homeland_secret_msg_10280 = "eu ouvi isso Fleur só fugiu porque foi assediado por seu superior na Illumina.",
  str_homeland_secret_msg_10281 = "A palavra é que BonacieA casa dela foi destruída por ela mesma.",
  str_homeland_secret_msg_10282 = "A última vez Bonacie se apresentou no concerto, até a Soroz dançou ao som de sua música.",
  str_homeland_secret_msg_10283 = "Apesar de quanto Bonacie adora música, ela não pode compor nada. Ela apenas age como se soubesse conduzir.",
  str_homeland_secret_msg_10284 = "Genevieve e Smokey deve ser um par, vendo como eles estão sempre juntos.",
  str_homeland_secret_msg_10285 = "A última vez em que Genevieve fiquei bêbada, ouvi dizer que ela \"fez alguma coisa\" com o Navigator ali mesmo no dormitório...",
  str_homeland_secret_msg_10286 = "eu ouvi isso Genevieve transformou sua empregada em um cavalo. É por isso que o cavalo é chamado de \"Anna\"...",
  str_homeland_secret_msg_10287 = "Pasolo tem uma bela caligrafia. Ela pratica a escrita todos os dias no dormitório. É por isso que ela sempre tem tantos pedaços de papel com ela.",
  str_homeland_secret_msg_10288 = "Há alguns dias, quando o Navigator tentou dizer Pasolo uma história, ela ficou chateada e chorou...",
  str_homeland_secret_msg_10289 = "Desde então Pasolo chegou ao dormitório, o chão nunca ficou limpo. Há sempre pedaços de papel no chão aqui ou ali!",
  str_homeland_secret_msg_10290 = "Gram pode até ficar bêbado de beber refrigerante.",
  str_homeland_secret_msg_10291 = "Gram parece ser quem cozinhou todas as refeições servidas no dormitório.",
  str_homeland_secret_msg_10292 = "Ouvi o som de um motor de carro roncando ontem à noite. Gram deve ter levado o carro dele para dar uma volta!",
  str_homeland_secret_msg_10293 = "Revy não pode ter qualquer comida picante. Ela chorou por um dia inteiro depois de comer um Spicy Cake anteriormente.",
  str_homeland_secret_msg_10294 = "Revy chamou o Navigator de \"boa pessoa\" da última vez. Isso significa...",
  str_homeland_secret_msg_10295 = "Revya espada de deve ser feita de madeira. De que outra forma ela poderia levantá-lo?",
  str_homeland_secret_msg_10296 = "Eu ouvi o Navegador e Allura abriram juntos uma loja de antiguidades em Umbraton, vendendo coisas de Caelestite por um preço baixo!",
  str_homeland_secret_msg_10297 = "Allura parece ter investido no Courier Union!",
  str_homeland_secret_msg_10298 = "ouvi Allura só se mudou para o Dormitório para ver se ela deveria comprá-lo.",
  str_homeland_secret_msg_10299 = "Paloma costumava trabalhar no Templo de Lumopolis. Ela foi expulsa porque quebrou uma estátua ou algo assim.",
  str_homeland_secret_msg_10300 = "Pact e Paloma são irmãs perdidas há muito tempo!",
  str_homeland_secret_msg_10301 = "Paloma e Pittman são colegas de classe. Eles realmente se conhecem!",
  str_homeland_secret_msg_10302 = "Ainda outro dia, vi o Navigator andando por aí Naroxelveado. Isso a deixou furiosa...",
  str_homeland_secret_msg_10303 = "Naroxel parece ser capaz de se comunicar com as árvores. São seus olhos e ouvidos.",
  str_homeland_secret_msg_10304 = "Naroxel tem muito medo de frio, então ela nunca vai chegar perto de Northland.",
  str_homeland_secret_msg_10305 = "Tweety é um especialista em lutas de bolas de neve! Ninguém no dormitório pode vencê-la!",
  str_homeland_secret_msg_10306 = "Tweety possui uma pousada inteira no Extremo Oriente. Ela é rica, como se vê!",
  str_homeland_secret_msg_10307 = "eu ouvi isso Tweety uma vez quis construir um dormitório de neve para todos... Ainda bem que não aconteceu.",
  str_homeland_secret_msg_10308 = "BethelO animal de estimação de parece ter comido toda a comida do dormitório.",
  str_homeland_secret_msg_10309 = "Bethel é na verdade um escritor famoso em Umbraton!",
  str_homeland_secret_msg_10310 = "eu ouvi isso Bethel é filha de Istvan!",
  str_homeland_secret_msg_10311 = "Eu vi Luke esboçando o Navigator no outro dia. Tinha toda a sua atenção.",
  str_homeland_secret_msg_10312 = "Assim que Luke veste aquela jaqueta dele, ele pode se transformar em borboleta e voar para longe.",
  str_homeland_secret_msg_10313 = "Nunca tente pegar uma borboleta. Luke enviará os mercenários para cuidar de você.",
  str_homeland_secret_msg_10314 = "Pittman costumava lutar na Arena Subterrânea com Tessa em Umbraton. Ele foi mesmo uma vez um campeão.",
  str_homeland_secret_msg_10315 = "Pittman perdeu o braço para os Eclipsites em Umbraton.",
  str_homeland_secret_msg_10316 = "Pittman é um leitor de velocidade. Ele termina um monte de arquivos todos os dias.",
  str_homeland_secret_msg_10317 = "Ouvi dizer que em Lumopolis, cada refeição custa Hedy milhões de Nightium!",
  str_homeland_secret_msg_10318 = "Ainda no outro dia, o Navigator assumiu Hedypor engano... e foi severamente punido por Pompeu por isso.",
  str_homeland_secret_msg_10319 = "Hedy não parece feliz com o dormitório. Ela queria construir um novo.",
  str_homeland_secret_msg_10320 = "Eu vi Cordy chorando para o Navigator alguns dias atrás, e ela continuou se desculpando...",
  str_homeland_secret_msg_10321 = "Apesar de Cordyé jovem, ela é uma xerife sênior em Illumina!",
  str_homeland_secret_msg_10322 = "Alguém viu Cordy fazendo três refeições tardias há alguns dias.",
  str_homeland_secret_msg_10323 = "Ouvi dizer que Hachi e Gin planejam comprar o Soroz. É por isso que eles estão aqui!",
  str_homeland_secret_msg_10324 = "Nunca toque no queixo de Hachi. Ele vai entrar em pânico.",
  str_homeland_secret_msg_10325 = "Gin não parece ter rabo...",
  str_homeland_secret_msg_10326 = "NovioA casa de 's é uma tribo selvagem nas profundezas das montanhas de Northland.",
  str_homeland_secret_msg_10327 = "NovioA equipe de parece ser capaz de falar!",
  str_homeland_secret_msg_10328 = "Rainha BethlehemO Palácio de Inverno parece ter sido construído por Novio.",
  str_homeland_secret_msg_10329 = "Lola é na verdade um coelhinho da Terra do Norte que virou auroriano!",
  str_homeland_secret_msg_10330 = "Não toque na marca Lolapescoço de, ou ela vai te caçar!",
  str_homeland_secret_msg_10331 = "Passei pela cozinha na outra noite e vi Lola comendo dormindo...",
  str_homeland_secret_msg_10332 = "Desde então Siobhan mudou-se para o dormitório, redes estranhas podem ser encontradas no telhado...",
  str_homeland_secret_msg_10333 = "Siobhan é na verdade uma antiga ela mesma. É por isso que ela está tão interessada em ruínas antigas.",
  str_homeland_secret_msg_10334 = "Não deixe Siobhan estar junto com Gronru. Eles não poderão fazer nada se isso acontecer.",
  str_homeland_secret_msg_10335 = "Erica não parece ser desta terra. Por que mais ela falaria de uma maneira tão estranha?",
  str_homeland_secret_msg_10336 = "Erica é realmente um profeta. Ela previu muitas coisas que desde então se tornaram realidade!",
  str_homeland_secret_msg_10337 = "Erica fez adivinhação para o Navegador há alguns dias, dizendo que o Navegador e Vice vai...",
  str_homeland_secret_msg_10338 = "O pano estranho Florine usa parece ser comprado na Illumina.",
  str_homeland_secret_msg_10339 = "FlorineA espada de é na verdade um cajado de cura!",
  str_homeland_secret_msg_10340 = "Florine perdeu sua cobra no dormitório...",
  str_homeland_secret_msg_10341 = "Ruby fez um buraco na parede do dormitório enquanto jogava beisebol... Ela quase derrubou o dormitório!",
  str_homeland_secret_msg_10342 = "Ruby pode ser uma exploradora ávida, mas não tem senso de direção.",
  str_homeland_secret_msg_10343 = "Ruby disse que seu hamster um dia salvará o mundo...",
  str_homeland_secret_msg_10344 = "eu ouvi isso RubyO hamster de é na verdade sua ração de emergência em tempos de necessidade.",
  str_homeland_secret_msg_10345 = "Rouge na verdade é vegano. Ela só gosta do cheiro de carne.",
  str_homeland_secret_msg_10346 = "Rouge realmente não tem medo de fantasmas. Ela apenas finge ter medo de Rubyamor de.",
  str_homeland_secret_msg_10347 = "Rouge só precisa de uma hora de sono por dia, então ela está apenas fingindo estar dormindo a maior parte do tempo.",
  str_homeland_secret_msg_10348 = "Há fantasmas no dormitório! Rinne descobriu que era verdade assim que ela chegou aqui!",
  str_homeland_secret_msg_10349 = "Rinne parece ser capaz de fazer adivinhação em relacionamentos românticos. Da última vez, ela disse Yao e Amemori vai...",
  str_homeland_secret_msg_10350 = "Se Rinne's Kagura Bell soa sozinho, algo ruim vai acontecer.",
  str_homeland_secret_msg_10351 = "Rinne parece ter sido um praticante em algum lugar muito, muito distante.",
  str_homeland_secret_msg_10352 = "eu ouvi isso Kayano mudou-se para o dormitório. Alguém já a viu?",
  str_homeland_secret_msg_10353 = "Kayano não é um auroriano, é? Por que mais ela teria tanto medo de outras pessoas?",
  str_homeland_secret_msg_10354 = "Kayano não anda. Ela flutua ao redor.",
  str_homeland_secret_msg_10355 = "Amemori precisa dormir mais de 16 horas por dia, mas é igualmente vigilante mesmo quando está dormindo.",
  str_homeland_secret_msg_10356 = "Amemori odeia alho!",
  str_homeland_secret_msg_10357 = "Amemori pode ficar invisível. Todos, tenham cuidado no dormitório!",
  str_homeland_secret_msg_10358 = "Alguns dias atrás, Yao quase comeu seu travesseiro enquanto ela dormia. Sério, eu vi!",
  str_homeland_secret_msg_10359 = "Yao não sabe nadar, mas pode flutuar muito bem na água.",
  str_homeland_secret_msg_10360 = "Mesmo quando Yao era apenas uma criança, ela derrotou milhares de piratas!",
  str_homeland_secret_msg_10361 = "Eu vi Yao compartilhar com Vice um prato de \"tofu não picante\" e depois...",
  str_homeland_secret_msg_10362 = "Momo secretamente aumentaria o total de mercadorias compradas!",
  str_homeland_secret_msg_10363 = "Anzu sempre usa o dedo para experimentar a sopa que está cozinhando!",
  str_homeland_secret_msg_10364 = "A loja de ramen de Momo e Anzu está abrindo uma filial aqui!",
  str_homeland_secret_msg_10365 = "TourdogO jogo de fez muito dinheiro!",
  str_homeland_secret_msg_10366 = "Quando em modo de trabalho, Tourdog pode trabalhar 25 horas por dia!",
  str_homeland_secret_msg_10367 = "Alguns nobres de Lumopolis parecem ter investido em Tourdog...",
  str_homeland_secret_msg_10368 = "eu ouvi isso Azure congelaria as pessoas que ela gosta!",
  str_homeland_secret_msg_10369 = "O bêbado Azure fica, melhor ela dirige!",
  str_homeland_secret_msg_10370 = "O Azure sempre leva o Navegador para um passeio, como se quisesse ser o treinador do Navegador.",
  str_homeland_secret_msg_10371 = "Azure parece ter dado ao seu carro um novo apelido: Caelestite Cutie.",
  str_homeland_secret_msg_10372 = "Roy chama suas abelhas-robô não apenas de \"Sweetie\", mas também de \"Caelee\" e \"Azurie\"...",
  str_homeland_secret_msg_10373 = "A última vez que o sistema de um Firefly travou, Roy acabei de chutar...",
  str_homeland_secret_msg_10374 = "Uma vez vi Roy ensinar o Navegador a costurar. Nunca pensei que ele tivesse esse tipo de talento...",
  str_homeland_secret_msg_10375 = "A mochila de gatinho de May originalmente tinha dois olhos. De alguma forma cresceu outro par...",
  str_homeland_secret_msg_10376 = "Quem falar com o gato branco de May receberá boa sorte!",
  str_homeland_secret_msg_10377 = "Da última vez, May deu dois rabos de cavalo ao Navegador. Foi adorável!",
  str_homeland_secret_msg_10378 = "Lenore não será capaz de se mover se ela não tocar suas orelhas. Ela disse que eles são suas \"molas de tensão\".",
  str_homeland_secret_msg_10379 = "Ainda outro dia, eu vi Lenore sorrindo para o Navegador e convidando o Navegador para seu quarto!",
  str_homeland_secret_msg_10380 = "Se você olhar de perto, Lenore não parece ter uma íris.",
  str_homeland_secret_msg_10381 = "Os chifres em Giles' cabeça crescer. Eles podem crescer até dois andares!",
  str_homeland_secret_msg_10382 = "Eu vi Giles levantando corvos no dormitório outro dia!",
  str_homeland_secret_msg_10383 = "Assim que Giles mudou-se, você pode ouvir uma voz estranha lendo rimas à noite no dormitório ...",
  str_homeland_secret_msg_10384 = "Alguns dias atrás, Reinhardt não conseguia nem abrir uma garrafa e teve que chamar o Navigator para ajudá-la.",
  str_homeland_secret_msg_10385 = "Eu vi Reinhardt lendo um romance em segredo!",
  str_homeland_secret_msg_10386 = "Alguém viu aquela foto antiga de Reinhardt com cabelo curto? Ela era tão fofa!",
  str_homeland_secret_msg_10387 = "Há rumores de que Reinhardt é realmente um cara!",
  str_homeland_secret_msg_10388 = "Os raios da morte saem Viceos olhos!",
  str_homeland_secret_msg_10389 = "eu ouvi isso Vice na verdade tem uma gêmea que se parece exatamente com ela!",
  str_homeland_secret_msg_10390 = "Agora isso Vice foi promovida, até mudou de guarda-roupa!",
  str_homeland_secret_msg_10391 = "eu ouvi isso {1} passou mal ultimamente, até o braço ficou estranho...",
  str_homeland_secret_msg_10392 = "{1} estava rindo como um louco no dormitório outro dia, dizendo que o dia de se tornar o \"verdadeiro General da Illumina\" está próximo... Então, quem é o General da Illumina agora?",
  str_homeland_secret_msg_10393 = "Eu vi {1} usando a espada de duas pontas para pegar peixe, e ele até assou o peixe com ela!",
  str_homeland_secret_msg_10394 = "É dito que Vice uma vez pensou que havia perdido um grampo de cabelo apenas para descobrir que o usava na parte de trás da cabeça.",
  str_homeland_secret_msg_10395 = "Dizem que a Sra. Blanc viaja com um jogo de chá completo!",
  str_homeland_secret_msg_10396 = "É dito que Dove tem um armazém cheio de encomendas à espera de entrega!",
  str_homeland_secret_msg_10397 = "Dizem que a arma de Raphael é tão pesada quanto uma casa!",
  str_homeland_secret_msg_10398 = "Nikinis ajustaria a flor em sua cabeça na frente do espelho quando ninguém estivesse olhando.",
  str_homeland_secret_msg_10399 = "É dito que Nina é um traficante de armas!",
  str_homeland_secret_msg_10400 = "Desde então Nina se mudou, todas as cortinas ficaram pretas!",
  str_homeland_secret_msg_10401 = "É dito que Nina não tem medo de fantasmas. Ela realmente gosta de conversar com eles!",
  str_homeland_secret_msg_10402 = "Nina tem sempre o guarda-sol aberto mesmo quando está a dormir!",
  str_homeland_secret_msg_10403 = "Sanae é um viajante de uma terra distante.",
  str_homeland_secret_msg_10404 = "Sanae sempre fala consigo mesma... Ela falaria em seu sonho?",
  str_homeland_secret_msg_10405 = "A sala parece tão cheia de Sanae e sua irmã se mudando...",
  str_homeland_secret_msg_10406 = "É dito que Carleen se tornará o Senhor da Cidade de Lumopolis!",
  str_homeland_secret_msg_10407 = "Apenas algumas noites atrás, os olhos de Carleen estavam brilhando!",
  str_homeland_secret_msg_10408 = "Você sabe sobre a arma de Carleen? É formado de Lumina e não tem forma física.",
  str_homeland_secret_msg_10409 = "Carleen parece ter ganhado uma nova habilidade. Ouvi dizer que ela pode controlar Lumopolis e fazê-la voar por toda parte.",
  str_homeland_secret_msg_10410 = "Ciel parecia ter feito um mecha enquanto dormia alguns dias atrás.",
  str_homeland_secret_msg_10411 = "A armadura de perna de Ciel parece ser uma parte de seu corpo. Ninguém a viu tirar.",
  str_homeland_secret_msg_10412 = "Parece que Ciel é bom em pintura!",
  str_homeland_secret_msg_10413 = "Fia pode se comunicar com animais!",
  str_homeland_secret_msg_10414 = "Esse cara Kyllo é dito ser a família de Fia!",
  str_homeland_secret_msg_10415 = "Parece que Fia pode se comunicar com todos os tipos de coisas, até com esta casa!",
  str_homeland_secret_msg_10416 = "Desde que Fia se mudou, tem havido muitos itens brilhantes. Será que ela é uma negociante de pedras preciosas?",
  str_homeland_secret_msg_10417 = "A adivinhação de Jeno acerta o alvo todas as vezes. Experimente se você não acredita nas minhas palavras!",
  str_homeland_secret_msg_10418 = "As mãos de Jeno são ocas e podem esconder coisas por dentro!",
  str_homeland_secret_msg_10419 = "Dizem que Jeno possui muitas cartas com padrões diferentes, e cada carta representa um grande evento no futuro!",
  str_homeland_secret_msg_10420 = "Na verdade, Jeno não sabe nada sobre truques de mágica. Tudo o que ele faz é real.",
  str_homeland_secret_msg_10421 = "Rainbow me disse que o navio tem alma!",
  str_homeland_secret_msg_10422 = "Ouvi pessoas dizerem que Rainbow é descendente da marinha que fugiu da Illumina!",
  str_homeland_secret_msg_10423 = "Rainbow tem muitos amigos! Mas seus nomes são muito estranhos: vara de pescar, tábuas de madeira, etc...",
  str_homeland_secret_msg_10424 = "Pollux é um anjo! Alguém uma vez viu uma auréola acima de sua cabeça.",
  str_homeland_secret_msg_10425 = "Aparentemente... as lágrimas de Pollux podem se transformar em pedras preciosas!",
  str_homeland_secret_msg_10426 = "Pollux parece ter monopolizado muitos negócios clandestinos em Umbraton e nem leva o Shadowlord a sério.",
  str_homeland_secret_msg_10427 = "Pollux é muito bom com crianças.",
  str_homeland_secret_msg_10428 = "Ouvi dizer que Casta dorme com seu rifle à noite.",
  str_homeland_secret_msg_10429 = "Às vezes, Casta até dorme debaixo da cama.",
  str_homeland_secret_msg_10430 = "Casta parece ter tido muita sorte recentemente. Ela vem ganhando jogos de adivinhação de dedos quase todas as vezes.",
  str_homeland_secret_msg_10431 = "Juiz Jr. é na verdade um plebeu. É por isso que ele não é promovido há tantos anos.",
  str_homeland_secret_msg_10432 = "Juiz Jr. é uma pessoa interpretada por várias pessoas que se revezam colocando uma máscara fingindo ser ele.",
  str_homeland_secret_msg_10433 = "O Juiz Jr. na verdade não sabe como julgar os casos. Ele só mexe.",
  str_homeland_secret_msg_10434 = "Dizem que Lilica é famosa em Umbraton! Ela veio aqui para ficar longe de seus fãs adoradores!",
  str_homeland_secret_msg_10435 = "Lilica parece ter comprado este dormitório. Não se esqueça de pagar o aluguel dela!",
  str_homeland_secret_msg_10436 = "Lilica veio aqui com a intenção de filmar um documentário sobre o amor e o ódio que brota neste lugar...",
  str_homeland_secret_msg_10437 = "Lilica realmente odeia atuar; ela só faz isso por consideração para seus fãs.",
  str_homeland_secret_msg_10438 = "Dizem que Minos estava em uma gangue durante seus dias em Umbraton. Melhor ficar do lado dele...",
  str_homeland_secret_msg_10439 = "Minos está secretamente criando uma vaca em algum lugar do dormitório. Isso explicaria os ocasionais mugidos à noite...",
  str_homeland_secret_msg_10440 = "Minos parece gostar muito de histórias de fantasmas.",
  str_homeland_secret_msg_10441 = "Mesmo que Minos seja muito forte, ele tem pavor de insetos! Deve ser por isso que ele limpa tudo tão meticulosamente.",
  str_homeland_secret_msg_10442 = "Sadie pode ser pequena, mas na verdade ela é incrivelmente poderosa! Ela pode pegar a casa inteira!",
  str_homeland_secret_msg_10443 = "Sadie diz que sonha em se tornar uma estrela do beisebol e que veio para Cloud Gardens procurar um lugar para construir um campo de beisebol!",
  str_homeland_secret_msg_10444 = "Sadie tem um apetite louco! Ela pode comer cem pedaços de bife sem suar a camisa, sem vegetais necessários!",
  str_homeland_secret_msg_10445 = "Na verdade, Axelia não pode falar. Estas são todas as mensagens pré-gravadas.",
  str_homeland_secret_msg_10446 = "Axelia parece jovem, mas é uma oficial de alto escalão da Federação Illumina.",
  str_homeland_secret_msg_10447 = "Na verdade, Axelia tem medo de insetos.",
  str_homeland_secret_msg_10448 = "Percebi que a cama de Axelia desabou debaixo dela alguns dias atrás. Ela pode ser muito pesada?",
  str_homeland_secret_msg_10449 = "Ouvi dizer que Beretta é bastante selvagem em batalha!",
  str_homeland_secret_msg_10450 = "Aparentemente, Beretta é a Mestra de Raphael!",
  str_homeland_secret_msg_10451 = "As duas lanças de Beretta podem se mover sozinhas, então não chegue perto dela à noite!",
  str_homeland_secret_msg_10452 = "Goldie parece odiar todas as coisas amargas!",
  str_homeland_secret_msg_10453 = "O cachorro de Goldie também é uma grande estrela. Ele estrelou em um comercial antes!",
  str_homeland_secret_msg_10454 = "Eu ouvi Goldie gritando uma vez! Acho que ela estava experimentando algo muito apertado...",
  str_homeland_secret_msg_10455 = "Não pegue o lado ruim de Goldie... Embora ela pareça um ídolo angelical, ela pode ser muito violenta.",
  str_homeland_secret_msg_10456 = "Vic pode parecer jovem, mas na verdade ele é um velhote...",
  str_homeland_secret_msg_10457 = "A última vez que vi Vic adormecer, ele chorou com aquele animal peludo nos braços, dizendo: \"Não consigo mais comer...\"",
  str_homeland_secret_msg_10458 = "Você pode ouvir os pássaros cantando no quarto de Vic a noite toda. É para dormir por aqui.",
  str_homeland_secret_msg_10459 = "Vic não é muito de beber! Suas bestas maravilhosas geralmente bebem toda a bebida que ele esconde.",
  str_homeland_secret_msg_10460 = "Brandy realmente ganhou o torneio Umbraton Arm Wrestling uma vez! Ela é tão forte!",
  str_homeland_secret_msg_10461 = "Até os Chubbs começaram a fofocar desde que Brandy chegou.",
  str_homeland_secret_msg_10462 = "A fofoca que Brandy sempre fala pode ser verdade. Afinal, ela é uma garota honesta.",
  str_homeland_secret_msg_10463 = "Ouvi dizer que a família de Zhong Xu se transformou em gatos!",
  str_homeland_secret_msg_10464 = "A cadeira de rodas de Zhong Xu supostamente pode voar!",
  str_homeland_secret_msg_10465 = "Zhong Xu parece não ter senso de direção. Ele está sempre procurando uma \"bússola\".",
  str_homeland_secret_msg_10466 = "Zhong Xu não pode lutar para salvar sua vida. Ele era funcionário público, por isso tem tantos pequenos artesanatos culturais.",
  str_homeland_secret_msg_10467 = "Yuebai supostamente não sabe nadar, então como ela se tornou capitã de um navio?",
  str_homeland_secret_msg_10468 = "Eu sinto que sempre que Yuebai sorri, algo ruim está prestes a acontecer...",
  str_homeland_secret_msg_10469 = "O sobrenome de Yuebai costumava ser Sen!",
  str_homeland_secret_msg_10470 = "Yuebai usa armadura de cota de malha completa o tempo todo, como se pensasse que alguém tentaria assassiná-la durante a noite!",
  str_homeland_secret_msg_10471 = "Ouvi dizer que Liqing pode comer qualquer coisa! Ele gosta particularmente de todos os tipos de grama... Talvez ele tenha sido um bode em uma vida passada!",
  str_homeland_secret_msg_10472 = "Na verdade, o remédio de Liqing é preparado de acordo com os ensinamentos médicos de seu mestre. Ele mesmo não teve nenhuma ideia.",
  str_homeland_secret_msg_10473 = "Liqing aparentemente tem um gato como irmão!",
  str_homeland_secret_msg_10474 = "Nemesis venceu o Concurso de Rap Illumina!",
  str_homeland_secret_msg_10475 = "Nemesis aprendeu a se teletransportar com membros da Courier Union!",
  str_homeland_secret_msg_10476 = "Acontece que toda a bebida que Siobhan tem bebido não é alcoólica, mas ela fica bêbada mesmo assim. O que posso dizer...",
  str_homeland_secret_msg_10477 = "Siobhan veio a Cloud Gardens para escavar estátuas de Colossus supostamente enterradas pelos Caelestitas.",
  str_homeland_secret_msg_10478 = "Aparentemente, Siobhan costumava ser uma estrela de cinema em Umbraton!",
  str_homeland_secret_msg_10479 = "Jeriah dorme com sua cobra à noite... Que terror!",
  str_homeland_secret_msg_10480 = "Há rumores de que Jeriah é a princesa de uma tribo do deserto!",
  str_homeland_secret_msg_10481 = "Desde que Jeriah chegou aqui, os dormitórios ficaram muito mais animados recentemente com os gritos de todos os tipos de animais...",
  str_homeland_secret_msg_10482 = "Jeriah parece ser vegetariano...",
  str_homeland_secret_msg_10483 = "Kya parece ter memória fotográfica! Impressionante!",
  str_homeland_secret_msg_10484 = "Embora Kya não pareça confiável, na verdade ela é muito madura! Por que mais ela seria tão boa em seu trabalho?",
  str_homeland_secret_msg_10485 = "Kya odeia frio, por isso está sempre entregando cartas.",
  str_homeland_secret_msg_10486 = "É verdade que Cuscuta traz boa sorte com ela onde quer que ela vá?",
  str_homeland_secret_msg_10487 = "Cuscuta realmente tem insônia. Seus olhos estão bem abertos, mesmo quando ela está dormindo.",
  str_homeland_secret_msg_10488 = "A pistola de água da Fia não está cheia de água, mas de algo que pode congelá-lo instantaneamente!",
  str_homeland_secret_msg_10489 = "Fia realmente tem uma voz muito bonita. Muitas pessoas não conseguem esquecê-lo depois de ouvi-la falar.",
  str_homeland_secret_msg_10490 = "Fia às vezes faz sons \"Lo ... Lo\". Ela está doente?",
  str_homeland_secret_msg_10491 = "A sonolência de Tina é falsa. A verdade é que ela tem insônia...",
  str_homeland_secret_msg_10492 = "O som do ronco encheu o dormitório desde então Tina mudou-se.",
  str_homeland_secret_msg_10493 = "Parece que coisas boas acontecem sempre Tina abre os olhos.",
  str_homeland_secret_msg_10494 = "Tina uma vez viajou com um Eclipsite!",
  str_homeland_secret_msg_10495 = "Olhe para a arma mecânica de Leyn. Ouvi dizer que Illumina fez isso para ele.",
  str_homeland_secret_msg_10496 = "Leyn tem um irmão há muito perdido que parece estar no deserto de Rediesel.",
  str_homeland_secret_msg_10497 = "Eu vi Leyn com alguns companheiros da Rediesel Wrench alguns dias atrás. Ele está pensando em desertar para eles?",
  str_homeland_secret_msg_10498 = "Leyn falou durante o sono algumas vezes. Parece que ele realmente quer uma família.",
  str_homeland_secret_msg_10499 = "A verdade é, Matthieu não sabe julgar casos!",
  str_homeland_secret_msg_10500 = "Desde Matthieu mudou-se, alguém parece estar limpando o dormitório todos os dias. Os quartos estão tão limpos agora.",
  str_homeland_secret_msg_10501 = "Ouvi dizer que a família de Matthieu tem uma joalheria.",
  str_homeland_secret_msg_10502 = "Na verdade, Hati adora colecionar bonecas, e pode ter certeza que muitas podem ser encontradas em sua casa.",
  str_homeland_secret_msg_10503 = "Hati tem uma inteligência superalta e não há palavras cruzadas que ela não consiga resolver.",
  str_homeland_secret_msg_10504 = "Parece que Hati foi criado por algum tipo de besta estranha...?",
  str_homeland_secret_msg_10505 = "Hati é muito bom em cozinhar! Sua especialidade é ensopado de carne!",
  str_homeland_secret_msg_10506 = "Desde Kristen mudou-se, ela pediu a todos que dobrassem suas colchas em um quadrado!",
  str_homeland_secret_msg_10507 = "Kristen uma vez praticou com sua lança em seu quarto, até que ela acabou abrindo um buraco no teto...",
  str_homeland_secret_msg_10508 = "O sonho de Kristen é ser a heroína de um show de ópera!",
  str_homeland_secret_msg_10509 = "Não se engane porque Yingel gosta de atirar à distância. Ela é realmente míope.",
  str_homeland_secret_msg_10510 = "Yingel bebeu muito de um certo leite alguns dias atrás e estava soluçando a noite toda.",
  str_homeland_secret_msg_10511 = "Parece que Yingel vai ficar doente depois de beber água com gás, então tome cuidado!",
  str_homeland_secret_msg_10512 = "Algum tipo de pássaro parece ter construído um ninho por aqui desde então Yingel mudou-se.",
  str_homeland_secret_msg_10513 = "Chocante! Leo realmente gosta de comer carne crua?!",
  str_homeland_secret_msg_10514 = "Parece que Leo traz uma banheira sempre que luta.",
  str_homeland_secret_msg_10515 = "Parece que Leo pode desenhar mapas em sua cabeça.",
  str_homeland_secret_msg_10516 = "Dizem que a ambição de Leo é se tornar o novo Lorde da Cidade de Lumopolis.",
  str_homeland_secret_msg_10517 = "Não pegue o lado ruim de Anatoli. Ele anotará em seu caderno e encontrará uma chance de se vingar.",
  str_homeland_secret_msg_10518 = "Anatoli tem excelente visão, ele pode ver as coisas claramente de muito longe, e pode ler lábios...",
  str_homeland_secret_msg_10519 = "Não chame a atenção de Anatoli, senão ele fará de tudo para te observar...",
  str_homeland_secret_msg_10520 = "Ele realmente mora aqui? Eu nem o tenho visto tanto por aí...",
  str_homeland_secret_msg_10521 = "Aquele sujeito parece ficar mais jovem do que antes!",
  str_homeland_secret_msg_10522 = "ouvi dizer que o Schwartz família tem uma técnica secreta para ficar jovem para sempre! Não é à toa que eles conseguiram governar Lumopolis por tanto tempo!",
  str_homeland_secret_msg_10523 = "Ela se tornou tão poderosa recentemente! Ela tem fugido para algum lugar para praticar?",
  str_homeland_secret_msg_10524 = "Depois que ela chegou, foi minha imaginação, ou o quarto dela estava cheio de cheiro de chá...?",
  str_homeland_secret_msg_10525 = "Uma princesa de Lumopolis acaba de se mudar!",
  str_homeland_secret_msg_10526 = "Ah! Parece que temos uma infestação de aranhas... E é das grandes!",
  str_homeland_secret_msg_10527 = "Sinto como se continuasse ouvindo alguém chamando\"Carleen, Carleen\" tarde da noite?",
  str_homeland_secret_msg_10528 = "Desde Jakine de Northland se mudou, notei flashes frequentes de luz nos dormitórios.",
  str_homeland_secret_msg_10529 = "Cobra! Jakine trouxe uma cobra aqui!",
  str_homeland_secret_msg_10530 = "Jakine não dorme à noite! Ela só quer festejar o tempo todo!",
  str_homeland_secret_msg_20001 = "{1} e {2} têm estilos de vida e hábitos muito diferentes. Um novo \"Illumina vs. Lumopolis\" acontecerá em breve no dormitório, marque minhas palavras.",
  str_homeland_secret_msg_20002 = "{1} queria abrir as janelas, e {2} queria que eles fechassem. Então eles continuaram abrindo e fechando as janelas a noite toda...",
  str_homeland_secret_msg_20003 = "Desde {1} mudou-se, {2}está ouvindo barulhos estranhos, e agora ela quer se mudar...",
  str_homeland_secret_msg_20004 = "Agora que ambos {1} e {2} mudou, até o ar parece sofisticado. Ah, mas eu não sou fã deles!",
  str_homeland_secret_msg_20005 = "Não deixe {1} e {2} viver juntos. eu ouvi isso {1} foi enganado por {2} no passado, então eles definitivamente entrarão em brigas. Espere. Não. As lutas já começaram ontem!",
  str_homeland_secret_msg_20006 = "{1} adora passar tempo com {2}! Não que eu goste de \"eles\", mas gosto do ar-condicionado natural que eles fazem...",
  str_homeland_secret_msg_20007 = "Quem aqui mora com {1} e {2}? É tão silencioso que você pode ouvir o menor dos sons ...",
  str_homeland_secret_msg_30001 = "Com {1} e {2} ao redor, até o dormitório parece um acampamento militar... Eles simplesmente não param de falar sobre estratégias e táticas.",
  str_homeland_secret_msg_30002 = "{1} disse que é preciso encarar a \"verdade\" enquanto {2} disse \"ser real\". Eu pensei que eles estavam tendo uma discussão filosófica, mas acabou que eles estavam discutindo o que jantar.",
  str_homeland_secret_msg_30003 = "Alguém entende o que {1} e {2} estão falando? Eu sei cada palavra que eles falam, mas eu não tenho a menor idéia do que eles querem dizer... Esse é o rumor do \"Umbraton-speak\"?",
  str_homeland_secret_msg_30004 = "\"Passarinho!\" {1} parece amar {2}penas. Pode ser porque isso {1} também é um animal? Hum... Deve ser mesmo!",
  str_homeland_secret_msg_30005 = "Até onde sei, {1} e {2} quebrar muitas canecas. 51, ainda ontem. É assim que eles praticam tiro?",
  str_homeland_secret_msg_30006 = "eu ouvi isso {2} comeu toda a comida {1} cozido antes mesmo de poder ser chapeado. . .",
  str_homeland_secret_msg_30007 = "Ouvi chamadas estranhas algumas noites atrás. Inicialmente, {2} pensei que eram os animais de estimação, mas depois acabou por ser {1}... Quero dizer, animais de estimação? Haha...",
  str_homeland_secret_msg_30008 = "Você pode sentir o ar endurecer assim que {1} e {2} estão na sala. Alguém já teve essa experiência?",
  str_homeland_secret_msg_30009 = "Alguns dias atrás, {2} mostrou algumas habilidades. {1} não disse nada, mas quando voltei para o dormitório, ouvi {1} murmurando algo sobre \"Illumina com certeza é impressionante.\"",
  str_homeland_secret_msg_30010 = "{1} sempre diz {2} não entende de música, mas isso também é o que {2} diz sobre {1}... Que par.",
  str_homeland_secret_msg_30011 = "Recentemente, {2} muitas vezes tem longas conversas com {1}. Ouvi dizer que um novo livro será lançado em breve!",
  str_homeland_secret_msg_30012 = "{2} parece precisar voltar ao Extremo Oriente, e {1} vai acompanhar.",
  str_homeland_secret_msg_30013 = "Alguém está seguindo {1} e tirando fotos. {2} está tentando descobrir... Quem poderia ser?",
  str_homeland_secret_msg_30014 = "{1} e {2} parecem ter encontrado algo de grande valor. Eles têm viajado sem se importar com o mundo ultimamente.",
  str_homeland_secret_msg_30015 = "{2} parece ter pego o que quer que seja {1}tem alguns dias atrás. Espero que não vire uma pandemia aqui...",
  str_homeland_secret_msg_30016 = "{1} contou uma história sobre como \"{2} tomou este lugar e o governou\" enquanto sonhava.",
  str_homeland_secret_msg_30017 = "eu ouvi isso {1} emprestou um pouco de Nightium de {2} mas nunca pagou. Como resultado, muitas vezes você pode ouvir algo sendo afiado por aqui.",
  str_homeland_secret_msg_30018 = "Alguns dizem que foi {1} e {2} que secretamente tapou os buracos no telhado do dormitório.",
  str_homeland_secret_msg_30019 = "{1} e {2} parecem sonâmbulos. Eles saíram por algumas noites.",
  str_homeland_secret_msg_30020 = "{1} parece ter ganho algum peso enquanto {2} perdeu alguns. A transferência de peso é uma coisa agora.",
  str_homeland_secret_msg_30021 = "{1} e {2} muitas vezes entrou em brigas sobre os vaga-lumes por algum motivo.",
  str_homeland_secret_msg_30022 = "Eu vi {1} e {2} vasculhando o diário do Navegador em segredo. Eles devem estar planejando algo contra o Navegador!",
  str_homeland_secret_msg_30023 = "eu ouvi isso {1} e {2} fez uma aposta no lado do dormitório com uma vista melhor."
}
return config
